local SoundpostMaker = {}
local PRODUCTS = {
    iron_soundpost = { name = "Železni zvočni stebriček", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni zvočni stebriček za glasbila." },
    bronze_soundpost = { name = "Bronast zvočni stebriček", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast zvočni stebriček za fino glasbo." },
    silver_soundpost = { name = "Srebrn zvočni stebriček", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn zvočni stebriček za plemiške glasbenike." },
    gilded_soundpost = { name = "Pozlačen zvočni stebriček", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen zvočni stebriček za dvorne glasbenike." },
    jewel_set_soundpost = { name = "Draguljast zvočni stebriček", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast zvočni stebriček za kraljevske glasbenike." },
    royal_sovereign_soundpost = { name = "Kraljevski suveren zvočni stebriček", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren zvočni stebriček z biseri za krono." },
}
local BUILDINGS = {
    soundpost_workshop = { name = "Soundpost delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    soundpost_house = { name = "Soundpost hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_soundpost_atelier = { name = "Mojstrski soundpost atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_soundpost_palace = { name = "Suverena soundpost palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
SoundpostMaker.ironStock = 12; SoundpostMaker.bronzeStock = 10; SoundpostMaker.woodStock = 18; SoundpostMaker.leatherStock = 10; SoundpostMaker.silverStock = 8; SoundpostMaker.goldStock = 6; SoundpostMaker.jewelStock = 4; SoundpostMaker.pearlStock = 4
SoundpostMaker.productStock = {}; SoundpostMaker.buildings = {}; SoundpostMaker.maker = nil; SoundpostMaker.activeMaking = {}; SoundpostMaker.totalProducts = 0; SoundpostMaker.dayTimer = 0
function SoundpostMaker.init() SoundpostMaker.ironStock=12; SoundpostMaker.bronzeStock=10; SoundpostMaker.woodStock=18; SoundpostMaker.leatherStock=10; SoundpostMaker.silverStock=8; SoundpostMaker.goldStock=6; SoundpostMaker.jewelStock=4; SoundpostMaker.pearlStock=4; SoundpostMaker.productStock={}; SoundpostMaker.buildings={}; SoundpostMaker.maker=nil; SoundpostMaker.activeMaking={}; SoundpostMaker.totalProducts=0; SoundpostMaker.dayTimer=0; print("[SoundpostMaker] Royal Soundpost Maker System initialized (6 products, 4 buildings)") end
function SoundpostMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SoundpostMaker.maker={name=n or ("Zvočar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zvočar najet: %s (spretnost: %d)",SoundpostMaker.maker.name,s),"success") end; return true end
function SoundpostMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SoundpostMaker.build(id) local ok,e=SoundpostMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SoundpostMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SoundpostMaker.getQualityBonus() local b=0; for _,bd in ipairs(SoundpostMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SoundpostMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SoundpostMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SoundpostMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SoundpostMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SoundpostMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SoundpostMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SoundpostMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SoundpostMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SoundpostMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SoundpostMaker.buildings==0 then return false,"Potrebna zvočna delavnica" end; if not SoundpostMaker.maker then return false,"Potreben zvocar" end; return true end
function SoundpostMaker.make(pt,qty) qty=qty or 1; local ok,e=SoundpostMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SoundpostMaker.ironStock=SoundpostMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SoundpostMaker.bronzeStock=SoundpostMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SoundpostMaker.woodStock=SoundpostMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SoundpostMaker.leatherStock=SoundpostMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SoundpostMaker.silverStock=SoundpostMaker.silverStock-d.silverCost*qty end; if d.goldCost then SoundpostMaker.goldStock=SoundpostMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SoundpostMaker.jewelStock=SoundpostMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SoundpostMaker.pearlStock=SoundpostMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SoundpostMaker.maker then t=math.max(1,t-math.floor(SoundpostMaker.maker.skill/13)) end; table.insert(SoundpostMaker.activeMaking,{id="soundpost_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SoundpostMaker.completeMaking(m) local q=1.0+(SoundpostMaker.getQualityBonus()/100); if SoundpostMaker.maker then q=q+(SoundpostMaker.maker.skill/140) end; q=math.min(2.5,q); SoundpostMaker.productStock[m.productType]=(SoundpostMaker.productStock[m.productType] or 0)+m.quantity; SoundpostMaker.totalProducts=SoundpostMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SoundpostMaker.maker then SoundpostMaker.maker.itemsMade=SoundpostMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SoundpostMaker.maker.skill=math.min(100,SoundpostMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stebriček izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"soundpost.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function SoundpostMaker.update(dt) if not _G.state then return end; SoundpostMaker.dayTimer=SoundpostMaker.dayTimer+dt; if SoundpostMaker.dayTimer>=30 then SoundpostMaker.dayTimer=0; for i=#SoundpostMaker.activeMaking,1,-1 do local m=SoundpostMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SoundpostMaker.completeMaking(m); table.remove(SoundpostMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SoundpostMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SoundpostMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SoundpostMaker.getStats() return {ironStock=SoundpostMaker.ironStock,bronzeStock=SoundpostMaker.bronzeStock,woodStock=SoundpostMaker.woodStock,leatherStock=SoundpostMaker.leatherStock,silverStock=SoundpostMaker.silverStock,goldStock=SoundpostMaker.goldStock,jewelStock=SoundpostMaker.jewelStock,pearlStock=SoundpostMaker.pearlStock,productStock=SoundpostMaker.productStock,numBuildings=#SoundpostMaker.buildings,hasMaker=SoundpostMaker.maker~=nil,makerName=SoundpostMaker.maker and SoundpostMaker.maker.name or "—",makerSkill=SoundpostMaker.maker and SoundpostMaker.maker.skill or 0,activeMaking=#SoundpostMaker.activeMaking,totalProducts=SoundpostMaker.totalProducts} end
return SoundpostMaker
